import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
// Specialized ConvTranspose3d forward kernel (stride=1, padding=0,
// output_padding=0, groups=1, dilation=1, fp32).
// Input : (16, 32, 16, 32, 64) contiguous fp32
// Weight: (32, 16, 3, 5, 7)  contiguous fp32 (ic, oc, kd, kh, kw)
// Bias  : (16) contiguous fp32 (optional)
// Output: (16, 16, 18, 36, 70) contiguous fp32
// Optimization: CTA handles all 16 output channels for one (n,d,h,W-tile).
// The zero-padded 16-channel input half is staged once and reused across
// all output channels before advancing to the next input-channel half,
// cutting repeated global input staging by the output-channel factor.
.visible .entry conv_transpose3d_kernel(
    .param .u64 param_in,
    .param .u64 param_w,
    .param .u64 param_b,
    .param .u64 param_out,
    .param .u32 param_total,
    .param .u32 param_has_bias
)
{
    .reg .pred %p, %pt, %rvalid, %pd, %ph, %pw0, %pw1, %pt6, %pty0;
    .reg .b32 %r_cta, %tx, %ty;
    .reg .b32 %wb, %t, %n, %d, %h, %w, %w0;
    .reg .b32 %ic, %icl, %icg, %half, %oc, %kd, %kh, %kw;
    .reg .b32 %dia, %hia, %wia, %dm2, %hm4, %w0m6;
    .reg .b32 %tmp, %tmp2, %tmp3, %tmp4, %idx, %in_off, %lane, %tap;
    .reg .b32 %sh_base_f, %sh_base_f6, %sidx, %out_idx, %red_i, %shw_base_f;
    .reg .b32 %total, %hasbias;
    .reg .b64 %in_base, %w_base, %b_base, %out_base;
    .reg .b64 %addr, %g_addr, %sh_addr, %sh_in_g, %sh_part_g, %sh_w_g, %sh_acc_g, %in_cb, %in_cb2, %w_cb;
    .reg .f32 %sum, %sum1, %acc, %acc1, %iv, %iv2, %wv, %wv1, %wv2, %wv3, %bv, %pv;
    .shared .align 4 .b8 sh_in[21120];
    .shared .align 4 .b8 sh_part[2048];
    .shared .align 16 .b8 sh_w[13568];
    .shared .align 4 .b8 sh_acc[1024];
    ld.param.u64 %in_base, [param_in];
    ld.param.u64 %w_base, [param_w];
    ld.param.u64 %b_base, [param_b];
    ld.param.u64 %out_base, [param_out];
    ld.param.u32 %total, [param_total];
    ld.param.u32 %hasbias, [param_has_bias];
    mov.u32 %r_cta, %ctaid.x;
    mov.u32 %tx, %tid.x;         // 0..15 output W lane inside tile
    mov.u32 %ty, %tid.y;         // channel lane in compute, oc lane in store
    // CTA tile decomposition: 5 W-tiles per (n, d, h); all oc are local.
    rem.u32 %wb, %r_cta, 5;
    div.u32 %t, %r_cta, 5;
    rem.u32 %h, %t, 36;
    div.u32 %t, %t, 36;
    rem.u32 %d, %t, 18;
    div.u32 %n, %t, 18;
    shl.b32 %w0, %wb, 4;
    add.s32 %w, %w0, %tx;
    setp.lt.u32 %rvalid, %w, 70;
    setp.eq.u32 %pty0, %ty, 0;
    sub.s32 %dm2, %d, 2;
    sub.s32 %hm4, %h, 4;
    sub.s32 %w0m6, %w0, 6;
    mul.lo.s32 %sh_base_f, %ty, 330;
    add.s32 %sh_base_f, %sh_base_f, %tx;
    add.s32 %sh_base_f6, %sh_base_f, 6;
    mov.u64 %sh_in_g, sh_in;
    mov.u64 %sh_part_g, sh_part;
    mov.u64 %sh_w_g, sh_w;
    mov.u64 %sh_acc_g, sh_acc;
    // Zero the per-CTA output-channel accumulator: 16 oc x 16 W floats.
    shl.b32 %lane, %ty, 4;
    add.s32 %lane, %lane, %tx;
    shl.b32 %tmp, %lane, 2;
    cvt.u64.u32 %addr, %tmp;
    add.s64 %addr, %addr, %sh_acc_g;
    mov.f32 %acc, 0f00000000;
    st.shared.f32 [%addr], %acc;
    bar.sync 0;
    mov.u32 %half, 0;
HALF_LOOP:
    setp.lt.u32 %p, %half, 2;
    @!%p bra HALF_DONE;
    shl.b32 %tmp, %half, 4;
    add.s32 %ic, %tmp, %ty;        // global input channel for this lane
    shl.b32 %tmp, %n, 5;
    add.s32 %tmp, %tmp, %ic;
    shl.b32 %in_off, %tmp, 15;     // channel base (floats)
    // ---- Stage this 16-channel half: zero-padded 3x5x22 window ----
    mov.u32 %kd, 0;
ST_DI:
    setp.lt.u32 %p, %kd, 3;
    @!%p bra ST_DI_END;
    add.s32 %dia, %dm2, %kd;
    setp.ge.s32 %pd, %dia, 0;
    setp.lt.s32 %pt, %dia, 16;
    and.pred %pd, %pd, %pt;
    shl.b32 %tmp, %dia, 11;
    add.s32 %tmp, %tmp, %in_off;
    mul.lo.s32 %tmp2, %kd, 110;
    add.s32 %tmp2, %tmp2, %sh_base_f;
    mov.u32 %kh, 0;
ST_HI:
    setp.lt.u32 %p, %kh, 5;
    @!%p bra ST_HI_END;
    add.s32 %hia, %hm4, %kh;
    setp.ge.s32 %ph, %hia, 0;
    setp.lt.s32 %pt, %hia, 32;
    and.pred %ph, %ph, %pt;
    and.pred %ph, %ph, %pd;
    shl.b32 %tmp3, %hia, 6;
    add.s32 %tmp3, %tmp3, %tmp;
    mul.lo.s32 %tmp4, %kh, 22;
    add.s32 %tmp4, %tmp4, %tmp2;
    shl.b32 %tmp4, %tmp4, 2;
    cvt.u64.u32 %addr, %tmp4;
    add.s64 %sh_addr, %sh_in_g, %addr;
    add.s32 %wia, %w0m6, %tx;
    setp.ge.s32 %pw0, %wia, 0;
    setp.lt.s32 %pt, %wia, 64;
    and.pred %pw0, %pw0, %pt;
    and.pred %pw0, %pw0, %ph;
    add.s32 %idx, %tmp3, %wia;
    mul.wide.u32 %g_addr, %idx, 4;
    add.s64 %g_addr, %g_addr, %in_base;
    mov.f32 %iv, 0f00000000;
    @%pw0 ld.global.f32 %iv, [%g_addr];
    st.shared.f32 [%sh_addr], %iv;
    setp.lt.u32 %pt6, %tx, 6;
    @!%pt6 bra ST_HI_NEXT;
    add.s32 %wia, %wia, 16;
    setp.lt.s32 %pw1, %wia, 64;
    and.pred %pw1, %pw1, %ph;
    add.s32 %idx, %tmp3, %wia;
    mul.wide.u32 %g_addr, %idx, 4;
    add.s64 %g_addr, %g_addr, %in_base;
    mov.f32 %iv, 0f00000000;
    @%pw1 ld.global.f32 %iv, [%g_addr];
    add.s64 %sh_addr, %sh_addr, 64;
    st.shared.f32 [%sh_addr], %iv;
ST_HI_NEXT:
    add.s32 %kh, %kh, 1;
    bra ST_HI;
ST_HI_END:
    add.s32 %kd, %kd, 1;
    bra ST_DI;
ST_DI_END:
    bar.sync 0;                    // staged input half ready
    // Reuse this staged input half for every output channel.
    mov.u32 %oc, 0;
OC_LOOP:
    setp.lt.u32 %p, %oc, 16;
    @!%p bra OC_DONE;
    // Stage this half/oc-pair weight slices interleaved (oc,oc+1) per tap, padded 212-float channel stride.
    mov.u32 %idx, %lane;
W_STAGE:
    setp.lt.u32 %p, %idx, 1680;
    @!%p bra W_STAGE_END;
    div.u32 %icl, %idx, 105;
    rem.u32 %tap, %idx, 105;
    shl.b32 %tmp2, %half, 4;
    add.s32 %icg, %tmp2, %icl;
    shl.b32 %tmp2, %icg, 4;
    add.s32 %tmp2, %tmp2, %oc;
    mul.lo.s32 %tmp2, %tmp2, 105;
    add.s32 %tmp2, %tmp2, %tap;
    mul.wide.u32 %g_addr, %tmp2, 4;
    add.s64 %g_addr, %g_addr, %w_base;
    ld.global.f32 %wv, [%g_addr];
    ld.global.f32 %wv1, [%g_addr+420];
    mul.lo.s32 %tmp3, %icl, 848;
    shl.b32 %tmp4, %tap, 3;
    add.s32 %tmp3, %tmp3, %tmp4;
    cvt.u64.u32 %addr, %tmp3;
    add.s64 %addr, %addr, %sh_w_g;
    st.shared.v2.f32 [%addr], {%wv, %wv1};
    add.s32 %idx, %idx, 256;
    bra W_STAGE;
W_STAGE_END:
    bar.sync 0;
    // ---- Compute this half for one output-channel pair ----
    // Register blocking over output channels with vectorized shared-memory
    // weight loads: oc/oc+1 taps are interleaved in sh_w so a single
    // ld.shared.v4 fetches both channels for a tap pair, halving weight
    // shared-load instructions while preserving per-channel FMA order.
    mov.f32 %sum, 0f00000000;
    mov.f32 %sum1, 0f00000000;
    mul.lo.s32 %shw_base_f, %ty, 212; // padded local-channel stride: 105 taps x 2 (oc pair) + 2
    shl.b32 %tmp, %sh_base_f6, 2;
    cvt.u64.u32 %in_cb, %tmp;
    add.s64 %in_cb, %in_cb, %sh_in_g;
    shl.b32 %tmp, %shw_base_f, 2;
    cvt.u64.u32 %w_cb, %tmp;
    add.s64 %w_cb, %w_cb, %sh_w_g;
    // kd = 0
    ld.shared.f32 %iv, [%in_cb+1232];
    ld.shared.f32 %iv2, [%in_cb+1228];
    ld.shared.v4.f32 {%wv,%wv1,%wv2,%wv3}, [%w_cb];
    fma.rn.f32 %sum, %iv, %wv, %sum;
    fma.rn.f32 %sum1, %iv, %wv1, %sum1;
    fma.rn.f32 %sum, %iv2, %wv2, %sum;
    fma.rn.f32 %sum1, %iv2, %wv3, %sum1;
    ld.shared.f32 %iv, [%in_cb+1224];
    ld.shared.f32 %iv2, [%in_cb+1220];
    ld.shared.v4.f32 {%wv,%wv1,%wv2,%wv3}, [%w_cb+16];
    fma.rn.f32 %sum, %iv, %wv, %sum;
    fma.rn.f32 %sum1, %iv, %wv1, %sum1;
    fma.rn.f32 %sum, %iv2, %wv2, %sum;
    fma.rn.f32 %sum1, %iv2, %wv3, %sum1;
    ld.shared.f32 %iv, [%in_cb+1216];
    ld.shared.f32 %iv2, [%in_cb+1212];
    ld.shared.v4.f32 {%wv,%wv1,%wv2,%wv3}, [%w_cb+32];
    fma.rn.f32 %sum, %iv, %wv, %sum;
    fma.rn.f32 %sum1, %iv, %wv1, %sum1;
    fma.rn.f32 %sum, %iv2, %wv2, %sum;
    fma.rn.f32 %sum1, %iv2, %wv3, %sum1;
    ld.shared.f32 %iv, [%in_cb+1208];
    ld.shared.f32 %iv2, [%in_cb+1144];
    ld.shared.v4.f32 {%wv,%wv1,%wv2,%wv3}, [%w_cb+48];
    fma.rn.f32 %sum, %iv, %wv, %sum;
    fma.rn.f32 %sum1, %iv, %wv1, %sum1;
    fma.rn.f32 %sum, %iv2, %wv2, %sum;
    fma.rn.f32 %sum1, %iv2, %wv3, %sum1;
    ld.shared.f32 %iv, [%in_cb+1140];
    ld.shared.f32 %iv2, [%in_cb+1136];
    ld.shared.v4.f32 {%wv,%wv1,%wv2,%wv3}, [%w_cb+64];
    fma.rn.f32 %sum, %iv, %wv, %sum;
    fma.rn.f32 %sum1, %iv, %wv1, %sum1;
    fma.rn.f32 %sum, %iv2, %wv2, %sum;
