    ld.shared.f32 %iv, [%in_cb+1124];
    ld.shared.f32 %iv2, [%in_cb+1120];
    ld.shared.v4.f32 {%wv,%wv1,%wv2,%wv3}, [%w_cb+96];
    fma.rn.f32 %sum, %iv, %wv, %sum;
    fma.rn.f32 %sum1, %iv, %wv1, %sum1;
    fma.rn.f32 %sum, %iv2, %wv2, %sum;
    fma.rn.f32 %sum1, %iv2, %wv3, %sum1;
    ld.shared.f32 %iv, [%in_cb+1056];
